changeSet.sql:
INSERT INTO subjects (id, name, description)
SELECT nextval('sequence_generator'), 'Mathematics', 'Môn Toán học - Kiến trúc Cây tri thức'
WHERE NOT EXISTS (
    SELECT 1 FROM subjects WHERE lower(name) IN ('mathematics', 'toán', 'toán học')
);

INSERT INTO subjects (id, name, description)
SELECT nextval('sequence_generator'), 'History', 'Môn Lịch sử - Kiến trúc Cây tri thức'
WHERE NOT EXISTS (
    SELECT 1 FROM subjects WHERE lower(name) IN ('history', 'lịch sử')
);
